class MetricSeries:
    namespace: str
    metric_name: str
    dimensions: dict[str, str]
    # (timestamp, value) sorted ascending.
    points: list[tuple[datetime, float]] = field(default_factory=list)
    # (seconds relative to the world anchor, value). A scenario written this way
    # keeps its shape wherever in wall-clock time it is served from, which is
    # what lets one document describe "the hour that just finished".
    relative_points: list[tuple[float, float]] = field(default_factory=list)
    unit: str = "None"

    def matches(self, namespace: str, metric_name: str, dimensions: dict[str, str]) -> bool:
        if namespace != self.namespace or metric_name != self.metric_name:
            return False
        return all(self.dimensions.get(k) == v for k, v in dimensions.items())

    def resolved_points(self, anchor: datetime) -> list[tuple[datetime, float]]:
        if not self.relative_points:
            return self.points
        shifted = [(anchor + timedelta(seconds=offset), value) for offset, value in self.relative_points]
        return sorted(self.points + shifted, key=lambda item: item[0])


