/** One step of the curve a dimension is read in, already clamped to the window. */
export type UsageStep = { start: Date; end: Date };

/** One published group of a dimension, read across the steps of the window. */
export type DimensionUsageGroup = {
    metadataGroup?: Record<string, string>;
    usage: UsageResponseDocument[] | BasicUsageDocument[];
};

/** The interval a dimension is read in, whatever case it was written in. */
const intervalOf = (interval: aggregationInterval): aggregationInterval =>
    aggregationInterval[String(interval ?? '').toLowerCase()] ?? aggregationInterval.hour;

/** The bucket edge on or before an instant, on the clock rather than the window. */
const alignToInterval = (instant: Date, interval: aggregationInterval): Date => {
    const year = instant.getUTCFullYear();
    const month = instant.getUTCMonth();
    const day = instant.getUTCDate();
    switch (interval) {
        case aggregationInterval.month:
            return new Date(Date.UTC(year, month, 1));
        case aggregationInterval.day:
            return new Date(Date.UTC(year, month, day));
        default:
            return new Date(Date.UTC(year, month, day, instant.getUTCHours()));
    }
};

/** The next bucket edge after one, on the clock. */
const nextIntervalEdge = (edge: Date, interval: aggregationInterval): Date => {
    switch (interval) {
        case aggregationInterval.month:
            return new Date(Date.UTC(edge.getUTCFullYear(), edge.getUTCMonth() + 1, 1));
        case aggregationInterval.day:
            return new Date(Date.UTC(edge.getUTCFullYear(), edge.getUTCMonth(), edge.getUTCDate() + 1));
        default:
            return new Date(edge.getTime() + 36e5);
    }
};

/**
 * Every step of the window, in order. The edges sit on the clock the way the
 * interval is counted, and the first and last step are clamped to the window so
 * a window that opens or closes mid bucket is not reported as more than it is.
 */
export const usageStepsOf = ({
    startTime,
    endTime,
    interval,
}: {
    startTime: string | Date;
    endTime: string | Date;
    interval: aggregationInterval;
}): UsageStep[] => {
    const windowStart = new Date(startTime);
    const windowEnd = new Date(endTime);
    const steps: UsageStep[] = [];
    if (!(windowEnd.getTime() > windowStart.getTime())) {
        return steps;
    }
    const every = intervalOf(interval);
    let edge = alignToInterval(windowStart, every);
    while (edge.getTime() < windowEnd.getTime()) {
        const next = nextIntervalEdge(edge, every);
        steps.push({
            start: edge.getTime() < windowStart.getTime() ? windowStart : edge,
            end: next.getTime() > windowEnd.getTime() ? windowEnd : next,
        });
        edge = next;
    }
    return steps;
};

/**
 * The readings of one series laid over the steps of the window. A step that
 * holds readings reports what the dimension's aggregation method makes of them.
 * A step that holds none reports nothing used, unless the dimension is
 * provisioned, in which case the level standing over it is carried through.
 */
export const stepUsageDocuments = ({
    steps,
    samples,
    method,
    carryLevel,
    standingLevel,
}: {
    steps: UsageStep[];
    samples: UsageSample[];
    method: aggregationMethod;
    carryLevel: boolean;
    standingLevel?: number;
}): UsageResponseDocument[] => {
    const readings = [...samples].sort((left, right) => left.timestamp.localeCompare(right.timestamp));
    let level = standingLevel;
    let next = 0;
    return steps.map(({ start, end }) => {
        const inStep: number[] = [];
        while (next < readings.length && new Date(readings[next].timestamp).getTime() < end.getTime()) {
            const reading = readings[next];
            if (new Date(reading.timestamp).getTime() >= start.getTime()) {
                inStep.push(reading.value);
            } else {
                // A reading the window does not cover still tells us the level.
                level = reading.value;
            }
            next += 1;
        }
        if (inStep.length) {
            level = inStep[inStep.length - 1];
        }
        const value = inStep.length
            ? reduceSamples(inStep, method)
            : carryLevel && level !== undefined
              ? level
              : 0;
        return new UsageDocument({
            value: value.toString(),
            startTime: start.toISOString(),
            endTime: end.toISOString(),
        });
    });
};

/** Whether a dimension holds a level between readings rather than counting them. */
const isProvisioned = (dimension: ReadDimensionResponseData): boolean =>
    String(dimension?.sampleType ?? '').toLowerCase() === SampleType.continious;

/** Whether a dimension is priced by the metadata groups its readings carry. */
const isMetadataPriced = (dimension: ReadDimensionResponseData): boolean =>
    Boolean(dimension?.tiersGroupByMetadata && dimension.tiersGroupByMetadata.length);

const metadataKey = (metadata: Record<string, string>): string =>
    Object.keys(metadata ?? {})
        .sort()
        .map((key) => `${key}=${metadata[key]}`)
        .join(',');

