new_map = '''    private static dimensionFunctionMap = {
        [usageData]: async ({
            businessID,
            startTime,
            endTime,
            dimension,
            customerId,
        }: SingleUsageEvent): Promise<DimensionUsageGroup[]> => {
            const {
                dimensionId,
                aggregationInterval: argumentAgg,
                aggregationMethod: argumentAggregationMethod,
            } = dimension as ReadDimensionResponseData;
            const windowStart = new Date(startTime);
            const windowEnd = new Date(endTime ?? new Date().toISOString());
            const published = await listUsageSeries({ businessID, customerId, dimensionId });

            if (intervalOf(argumentAgg) !== aggregationInterval.none) {
                const steps = usageStepsOf({
                    startTime: windowStart,
                    endTime: windowEnd,
                    interval: argumentAgg,
                });
                const provisioned = isProvisioned(dimension as ReadDimensionResponseData);
                const readingsOf = async (group: UsageSeries[]): Promise<UsageSample[]> => {
                    const samples: UsageSample[] = [];
                    for (const series of group) {
                        samples.push(
                            ...(await readUsageSamples({
                                series,
                                startTime: windowStart,
                                endTime: windowEnd,
                            })),
                        );
                    }
                    return samples;
                };
                // A provisioned dimension holds whatever level it was last set
                // to, and that setting may be older than the window.
                const levelBefore = async (group: UsageSeries[]): Promise<number | undefined> => {
                    if (!provisioned) {
                        return undefined;
                    }
                    let standing: UsageSample | undefined;
                    for (const series of group) {
                        const sample = await readLatestUsageSampleBefore({ series, before: windowStart });
                        if (sample && (standing === undefined || sample.timestamp > standing.timestamp)) {
                            standing = sample;
                        }
                    }
                    return standing?.value;
                };
                const curveOf = async (group: UsageSeries[]): Promise<UsageResponseDocument[]> =>
                    stepUsageDocuments({
                        steps,
                        samples: await readingsOf(group),
                        method: argumentAggregationMethod,
                        carryLevel: provisioned,
                        standingLevel: await levelBefore(group),
                    });

                if (isMetadataPriced(dimension as ReadDimensionResponseData) && published.length) {
                    // Every group a dimension priced by metadata has published
                    // is a curve of its own, the plain series included.
                    const groups = published.reduce(
                        (acc, series) => {
                            const metadata = metadataOf(series);
                            const key = metadataKey(metadata);
                            acc[key] = acc[key] ?? { metadata, series: [] };
                            acc[key].series.push(series);
                            return acc;
                        },
                        {} as Record<string, { metadata: Record<string, string>; series: UsageSeries[] }>,
                    );
                    const grouped: DimensionUsageGroup[] = [];
                    for (const key of Object.keys(groups).sort()) {
                        const { metadata, series } = groups[key];
                        grouped.push({
                            metadataGroup: Object.keys(metadata).length ? metadata : undefined,
                            usage: await curveOf(series),
                        });
                    }
                    return grouped;
                }

                // Everything published for the dimension makes up the one
                // curve, and a customer with nothing published still gets the
                // steps of the window.
                return [{ usage: await curveOf(published) }];
            }

            const unAggregatedResults: BasicUsageDocument[] = [];
            for (const series of published) {
                const samples = await readUsageSamples({
                    series,
                    startTime: windowStart,
                    endTime: windowEnd,
                });
                const metadata = metadataOf(series);
                samples.forEach(({ timestamp, value }) => {
                    unAggregatedResults.push({ timestamp, recordValue: value.toString(), metadata });
                });
            }
            return [{ usage: unAggregatedResults }];
        },
    };

