const sameSeries = (left: Record<string, string>, right: Record<string, string>): boolean =>
    Object.keys(left).length === Object.keys(right).length &&
    Object.keys(left).every((key) => left[key] === right[key]);

jest.mock('../utils/aws/cloudwatchUsage.js', () => ({
    METADATA_DIMENSION_PREFIX: 'Metadata_',
    usageSeriesOf: ({ businessID, customerId, dimensionId }) => ({
        BusinessId: businessID,
        CustomerId: customerId,
        DimensionId: dimensionId,
    }),
    metadataOf: (series) =>
        Object.keys(series)
            .filter((name) => name.startsWith('Metadata_'))
            .sort()
            .reduce((acc, name) => {
                acc[name.slice('Metadata_'.length)] = series[name];
                return acc;
            }, {}),
    listUsageSeries: jest.fn(async ({ businessID, customerId, dimensionId }) =>
        published
            .filter(
                ({ series }) =>
                    series.BusinessId === businessID &&
                    series.CustomerId === customerId &&
                    series.DimensionId === dimensionId,
            )
            .map(({ series }) => series),
    ),
    readUsageSamples: jest.fn(async ({ series, startTime, endTime }) =>
        (published.find((entry) => sameSeries(entry.series, series))?.points ?? []).filter(
            ({ timestamp }) =>
                new Date(timestamp).getTime() >= new Date(startTime).getTime() &&
                new Date(timestamp).getTime() < new Date(endTime).getTime(),
        ),
    ),
    readLatestUsageSampleBefore: jest.fn(async ({ series, before }) =>
        (published.find((entry) => sameSeries(entry.series, series))?.points ?? [])
            .filter(({ timestamp }) => new Date(timestamp).getTime() < new Date(before).getTime())
            .pop(),
    ),
}));

const dimension = (dimensionId: string, overrides = {}) => ({
    dimensionId,
    aggregationInterval: aggregationInterval.hour,
    aggregationMethod: aggregationMethod.sum,
    sampleType: SampleType.gauge,
    ...overrides,
});

const readUsage = (dimensions: any[], startTime: string, endTime: string) =>
    UsageAggregationEvent.getAggregateUsageForDimension({
        businessID: 'biz',
        customerId: 'cus',
        clientID: 'cus',
        startTime,
        endTime,
