describe('usage read in steps', () => {
    describe('usageStepsOf', () => {
        it('aligns the edges to the clock and clamps them to the window', () => {
            const steps = usageStepsOf({
                startTime: '2024-02-14T00:40:00Z',
                endTime: '2024-02-14T02:20:00Z',
                interval: aggregationInterval.hour,
            });
            expect(steps.map(({ start, end }) => [start.toISOString(), end.toISOString()])).toEqual([
                ['2024-02-14T00:40:00.000Z', '2024-02-14T01:00:00.000Z'],
                ['2024-02-14T01:00:00.000Z', '2024-02-14T02:00:00.000Z'],
                ['2024-02-14T02:00:00.000Z', '2024-02-14T02:20:00.000Z'],
            ]);
        });
        it('counts days and months on the clock too', () => {
            expect(
                usageStepsOf({
                    startTime: '2024-01-15T06:00:00Z',
                    endTime: '2024-03-02T00:00:00Z',
                    interval: aggregationInterval.month,
                }).map(({ start, end }) => [start.toISOString(), end.toISOString()]),
            ).toEqual([
                ['2024-01-15T06:00:00.000Z', '2024-02-01T00:00:00.000Z'],
                ['2024-02-01T00:00:00.000Z', '2024-03-01T00:00:00.000Z'],
                ['2024-03-01T00:00:00.000Z', '2024-03-02T00:00:00.000Z'],
            ]);
            expect(
                usageStepsOf({
                    startTime: '2024-02-12T00:00:00Z',
                    endTime: '2024-02-14T00:00:00Z',
                    interval: aggregationInterval.day,
                }).map(({ start }) => start.toISOString()),
            ).toEqual(['2024-02-12T00:00:00.000Z', '2024-02-13T00:00:00.000Z']);
        });
    });

    it('reports a step for every interval of the window, unused ones as nothing', async () => {
        const [requests] = await readUsage(
            [dimension('requests')],
            '2024-02-14T00:40:00Z',
            '2024-02-14T02:20:00Z',
        );
        expect(requests).toEqual({
            offeringId: 'off',
            dimensionId: 'requests',
            usage: [
                { value: '3', startTime: '2024-02-14T00:40:00.000Z', endTime: '2024-02-14T01:00:00.000Z' },
                { value: '0', startTime: '2024-02-14T01:00:00.000Z', endTime: '2024-02-14T02:00:00.000Z' },
                { value: '6', startTime: '2024-02-14T02:00:00.000Z', endTime: '2024-02-14T02:20:00.000Z' },
            ],
        });
    });

    it('carries the standing level of a provisioned dimension through quiet steps', async () => {
        const [seats] = await readUsage(
            [
                dimension('seats', {
                    aggregationMethod: aggregationMethod.max,
                    sampleType: SampleType.continious,
                }),
            ],
            '2024-02-14T00:40:00Z',
            '2024-02-14T02:20:00Z',
        );
        expect(seats.usage.map(({ value }) => value)).toEqual(['2', '5', '5']);
    });

    it('reports every published group of a dimension priced by metadata separately', async () => {
        const groups = await readUsage(
            [
                dimension('egress', {
                    tiersGroupByMetadata: [
                        {
                            metadataGroups: { environment: 'production' },
                            tiers: [{ lowerLimit: '0', upperLimit: 'inf', price: '0.01' }],
                        },
                    ],
                }),
            ],
            '2024-02-14T00:40:00Z',
            '2024-02-14T02:20:00Z',
        );
        expect(groups.map(({ metadataGroup, usage }: any) => [metadataGroup, usage.map(({ value }) => value)])).toEqual(
            [
