                [{ environment: 'staging' }, ['0', '9', '0']],
            ],
        );
    });

    it('reports every step of a dimension the customer has never published', async () => {
        const [quiet] = await readUsage(
            [dimension('quiet', { aggregationInterval: aggregationInterval.day })],
            '2024-02-12T00:00:00Z',
            '2024-02-14T00:00:00Z',
        );
        expect(quiet.usage).toEqual([
            { value: '0', startTime: '2024-02-12T00:00:00.000Z', endTime: '2024-02-13T00:00:00.000Z' },
            { value: '0', startTime: '2024-02-13T00:00:00.000Z', endTime: '2024-02-14T00:00:00.000Z' },
        ]);
    });

    it('hands back the readings themselves when no interval is asked for', async () => {
        const [requests] = await readUsage(
            [dimension('requests', { aggregationInterval: aggregationInterval.none })],
            '2024-02-14T00:40:00Z',
            '2024-02-14T02:20:00Z',
        );
        expect(requests.usage).toEqual([
            { timestamp: '2024-02-14T00:45:00.000Z', recordValue: '1', metadata: {} },
            { timestamp: '2024-02-14T00:50:00.000Z', recordValue: '2', metadata: {} },
            { timestamp: '2024-02-14T02:05:00.000Z', recordValue: '6', metadata: {} },
        ]);
    });
});
